#include <algorithm>
#include <cstdio>
using namespace std;
const int N = 15;
int n, m;
int a[N][N];
int ans;
int main() {
    scanf("%d%d", &n, &m);
    for (int i = 1; i <= n; i++)
        for (int j = 1; j <= m; j++) scanf("%d", &a[i][j]);
    for (int u = 1; u <= n; u++)
        for (int l = 1; l <= m; l++)
            for (int d = u; d <= n; d++) {
                int chk = 1;
                for (int r = l; r <= m; r++) {
                    for (int x = u; x <= d; x++) chk &= a[x][r];
                    if (!chk) break;
                    ans = max(ans, (r - l + 1) * (d - u + 1));
                }
            }
    printf("%d\n", ans);
    return 0;
}

#include <algorithm>
#include <cstdio>
using namespace std;
const int N = 1e5 + 5;
int n;
int a[N];
int last, cnt, mx;
int main() {
    scanf("%d", &n);
    for (int i = 1; i <= n; i++) scanf("%d", &a[i]);
    sort(a + 1, a + n + 1);
    last = a[1];
    cnt = mx = 1;
    for (int i = 1; i <= n; i++) {
        if (a[i] == last) continue;
        if (a[i] == last + 1)
            cnt++;
        else
            cnt = 1;
        last = a[i];
        mx = max(cnt, mx);
    }
    printf("%d\n", mx);
    return 0;
}
